        body: '### Critical Examiner Traps\n- **Trap 1: Tariffs in Large vs Small Countries**: In a small country, a tariff *always* reduces national welfare (deadweight loss $b + d$). In a **large country** (capable of affecting world prices), a tariff can theoretically improve national welfare if the **Terms of Trade gain (area $e$)** exceeds the deadweight loss (the Optimum Tariff argument).\n- **Trap 2: Quota Rents Allocation**: A quota does NOT yield government revenue unless the government auctions licenses. If licenses are given free to importers (First-Come-First-Served or historical quota), the revenue is captured as private **Quota Rent**.\n- **Trap 3: Export Subsidies Make Goods Cheaper Domestically**: False! An export subsidy makes the good **more expensive domestically** ($P_d = P_w + s$) because domestic producers will refuse to sell locally unless local buyers match the subsidized export price.\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: Geometric decomposition of deadweight loss areas ($a, b, c, d$), quota rents, and optimum tariff theory.\n- **UPSC APFC, IIBF DBF & RPSC RAS**: Definitions of specific vs ad valorem tariffs, tariff-quota equivalents, and anti-dumping duties.',
