        body: 'The Effective Rate of Protection is defined as the percentage increase in value added per unit of output made possible by the tariff structure compared to free trade:\n\n$$ERP = \\frac{V\' - V}{V}$$\n- $V$ = Value added under free trade per unit of output.\n- $V\'$ = Value added under the tariff structure per unit of output.\n\n### The Corden-Balassa Formula\n$$ERP = \\frac{t_f - a \\cdot t_i}{1 - a}$$\n- $t_f$ = Nominal tariff rate on the final good.\n- $t_i$ = Nominal tariff rate on imported intermediate inputs.\n- $a$ = Ratio of the cost of imported inputs to the price of the final good under free trade ($a = \\frac{\\text{Input Cost}}{\\text{Final Price}}$).\n\n### Three Critical Tariff Structure Scenarios\n1. **Cascading Tariffs ($t_i < t_f$) $\\implies ERP > t_f$**: Effective protection on domestic value added exceeds the nominal tariff on the finished good.\n2. **Uniform Tariffs ($t_i = t_f$) $\\implies ERP = t_f$**: Effective protection equals the nominal tariff.\n3. **Negative Effective Protection ($t_i > \\frac{t_f}{a}$) $\\implies ERP < 0$**: High duties on raw materials with low duties on finished products actually tax and penalize domestic manufacturers relative to free trade!',
