        type: 'INTUITION',
        title: 'Above the Line vs Below the Line: Why the Central Bank Steps In',
        body: 'Imagine an entire year of commercial activity in India:\n- Exporters, importers, IT companies, tourists, and corporate investors make decisions for their own profits. Nobody asks: *"Will my transaction balance the national BoP?"* These are **Autonomous ("Above the Line") Transactions**.\n\nAt the end of the year, suppose total autonomous dollar outflows (imports, loan payments, outward capital) totaled **US \\USD 800 Billionillion**, while total autonomous dollar inflows (exports, remittances, FDI) totaled only **US \\USD 750 Billionillion**.\n\nThere is an autonomous shortfall of **US \\USD 50 Billionillion**. The private market cannot magically create US dollars. The **Reserve Bank of India (RBI)** must step in and provide US \\USD 50 Billionillion from its official foreign exchange reserves to ensure Indian importers and banks do not default on their global obligations.\n\nThe RBI\'s reserve action is an **Accommodating ("Below the Line") Transaction**.',
        order: 1,
