        body: '### Critical Examiner Traps\n- **Trap 1: The Reserve Sign Convention in BPM6**: In BPM6 accounting, an **increase in official reserves** is recorded with a **minus sign (-)** because the central bank is acquiring an external asset (an outflow of domestic liquidity). A **decrease in reserves** is recorded with a **plus sign (+)** as a source of funds!\n- **Trap 2: Is Government Borrowing Always Accommodating?**: No! If the government issues sovereign green bonds or raises commercial debt for an infrastructure project, it is an **autonomous capital inflow**. If the government borrows from the IMF to prevent a sovereign default during a currency crisis (like India in 1991), it is **accommodating**.\n- **Trap 3: "BoP Deficit" vs "Current Account Deficit"**: A country can have a large Current Account Deficit (CAD) but still enjoy an **Overall BoP Surplus** if autonomous capital inflows (FDI + FPI + ECBs) are larger than the CAD (as India frequently experiences).\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: Distinguishing autonomous from accommodating flows, official reserve transactions, and BPM6 sign conventions.\n- **UPSC APFC, SBI/IBPS PO & RPSC RAS**: Conceptual definitions of "Above the Line" vs "Below the Line" items.',
