        body: 'Every month, news headlines report: *"India\'s Trade Deficit reaches US \\\\USD 20 Billionillion!"* Many citizens panic, assuming India lost US \\\\USD 20 Billionillion in foreign exchange.\n\nHere is why that panic is misguided:\n- **Merchandise Trade** covers only physical, visible goods (oil, gold, mobile phones, coal). Because India is energy-poor, we import far more physical goods than we export (**Trade Deficit**).\n- But India is a **Services Superpower**: Infosys, TCS, and thousands of tech firms export billions of dollars of software and consulting every month (**Net Services Surplus**).\n- Millions of Indians working in the Gulf, USA, and UK send money home to their families (**Remittances / Secondary Income**).\n\nWhen you add software earnings + remittances, they cancel out roughly **70% to 80% of our physical goods deficit**! That is why **Trade Balance $\\\\neq$ Current Account Balance**.',
