        title: 'Building a Factory vs Buying Shares on a Smartphone',
        body: 'Consider two foreign investors putting money into India:\n1. **Investor A (FDI)**: Japanese auto giant Suzuki invests ₹10,000 Crore to build a mega car manufacturing plant in Gujarat. Suzuki hires 5,000 workers, trains engineers, and builds physical machinery. Can Suzuki press a button on a smartphone and pull its ₹10,000 Crore out of India tomorrow morning? **No.** The factory is physically bolted to Indian soil. This is **Foreign Direct Investment (FDI)**: stable, non-debt creating, and long-term.\n2. **Investor B (FPI)**: A hedge fund in New York buys ₹100 Crore worth of shares in Indian IT companies on the National Stock Exchange. Three weeks later, the US Federal Reserve raises interest rates. The hedge fund clicks "Sell" on its terminal, converts Rupees to US Dollars, and leaves India in **30 seconds**. This is **Foreign Portfolio Investment (FPI / "Hot Money")**: highly liquid, volatile, and reversible.\n\nDeveloping nations welcome FPI for stock market liquidity, but rely on FDI for enduring industrial growth.',
