        type: 'INTUITION',
        title: 'The Onion Market Analogy for US Dollars in Mumbai',
        body: 'Think of the US Dollar as a commodity, just like onions in a wholesale mandi in Nashik:\n- When a bad monsoon destroys onion crops, the supply of onions shrinks, and the price of onions shoots up from ₹30/kg to ₹80/kg.\n- In the Mumbai foreign exchange market, the **US Dollar is the commodity** and the **Indian Rupee is the price**.\n\nWhat makes the price of a Dollar rise from ₹80 to ₹85 (**Rupee Depreciation**)?\n1. **High Demand for Dollars**: Global crude oil prices surge, so Indian oil refiners rush to buy billions of US Dollars to pay Saudi Aramco.\n2. **Low Supply of Dollars**: Foreign investors panic and sell Indian stocks, reducing the inflow of fresh US Dollars into Mumbai.\n\nWhen demand for dollars exceeds supply, the price of 1 Dollar goes up in Rupees (from ₹80 to ₹85). The Rupee has **depreciated**, and the Dollar has **appreciated**.',
