        title: 'The Shock Absorber vs The Anchor: Choosing an Exchange Rate Regime',
        body: 'Imagine driving a car over a rocky mountain road:\n1. **A Fixed Exchange Rate is a Rigid Steel Axle**: It provides total price certainty to businesses (no currency risk). But when a massive external shock hits (e.g., global oil prices double), the rigid axle cannot bend. The entire shock smashes directly into the domestic economy—causing factory closures, wage cuts, unemployment, and potential currency collapse when the central bank runs out of dollar reserves.\n2. **A Free Floating Exchange Rate is a Soft Hydraulic Shock Absorber**: When global oil prices surge, the currency instantly depreciates by 10%. This price change immediately makes foreign goods expensive, curbs domestic oil demand, makes domestic exports cheaper, and automatically absorbs the shock without forcing domestic wages down or depleting reserves.\n\nMost nations (including India) choose a **Managed Float**: let the hydraulic shock absorber work to reflect economic reality, but step on the brakes if the car begins violently spinning out of control.',
