        body: 'Suppose you export leather shoes from Agra to Berlin. In Year 1, the exchange rate is ₹80 / Euro, and your shoes cost ₹8,000 to manufacture. In Germany, your shoes sell for **100 Euros**.\n\nIn Year 2, the Rupee depreciates by $10\\%$ to ₹88 / Euro. You celebrate, thinking your shoes will become cheaper in Germany! But during the year, Indian inflation was $10\\%$, so your leather, labor, and electricity costs shot up from ₹8,000 to ₹8,800.\n\nWhat is your price in Germany now? $\\\\frac{₹8,800}{₹88} =$ **100 Euros**!\n\nEven though the **Nominal Exchange Rate** depreciated by 10%, your **Real Exchange Rate** did not change at all because domestic inflation wiped out the currency gain. Your real export competitiveness in Berlin remained completely identical.',
