        type: 'CORE_IDEA',
        title: 'Mathematical Formulation of NEER and REER',
        body: 'To eliminate bilateral distortions, central banks construct trade-weighted multilateral indices:\n\n### 1. Nominal Effective Exchange Rate (NEER)\n$$NEER = \\\\prod_{i=1}^{n} \\\\left( \\\\frac{e_i}{e_{i,0}} \\\\right)^{w_i} \\\\times 100$$\n- $e_i$: Bilateral exchange rate of the Rupee against currency $i$.\n- $w_i$: Trade weight of country $i$ in India\'s total trade (exports + imports), where $\\\\sum w_i = 1$.\n- $n$: Number of partner countries (40-currency basket for broad index; 6-currency basket for major advanced peers).\n\n### 2. Real Effective Exchange Rate (REER)\n$$REER = \\\\prod_{i=1}^{n} \\\\left[ \\\\left( \\\\frac{e_i}{e_{i,0}} \\\\right) \\\\times \\\\left( \\\\frac{P}{P_i} \\\\right) \\\\right]^{w_i} \\\\times 100$$\n- $P$: Domestic Consumer Price Index (CPI) of India.\n- $P_i$: Consumer Price Index (CPI) of partner country $i$.\n\n### 3. Interpreting REER Benchmark Values (Base = 100)\n- **REER = 100**: Rupee is trading at fair real macroeconomic parity against trading partners.\n- **REER > 100 (e.g., REER = 105)**: The Rupee is **Overvalued** by 5% in real terms. Indian goods are relatively more expensive abroad $\\\\implies$ **Loss of export price competitiveness**; imports become artificially cheaper.\n- **REER < 100 (e.g., REER = 95)**: The Rupee is **Undervalued** by 5% in real terms. Indian goods are cheaper in global markets $\\\\implies$ **Gain in export price competitiveness**.',
