        body: 'Why is a haircut in Jaipur priced at ₹200 (about US \\$2.40), while an identical haircut in Manhattan costs US \\$30 (about ₹2,500)?\n- Can you box up a Jaipur barber and export his service across the Atlantic to sell in Manhattan for US \\$30? **No.** Haircuts, restaurant dining, rent, and domestic transport are **Non-Tradable Goods**.\n- In Manhattan, high productivity in Wall Street and Silicon Valley drives up wages for *everyone*, including barbers.\n- In Jaipur, lower average industrial wages keep service prices very cheap.\n\nBecause non-tradables are cheap in developing countries, **₹84 in Jaipur buys far more food, haircuts, and domestic living than US \\$1 buys in New York**.\n\nThis is why India\'s GDP at market exchange rates is $\\\\sim \\\\text{US \\\\USD 4 Trillionrillion}$, but when measured in **Purchasing Power Parity (PPP)**, India\'s GDP is $\\\\sim \\\\text{US \\\\USD 14 Trillionrillion}$ (the 3rd largest in the world behind China and the USA)! This insight is the **Balassa-Samuelson Effect**.',
