        type: 'CORE_IDEA',
        title: 'The Parity Theories Mathematical Taxonomy',
        body: 'International macroeconomics rests on three foundational parity conditions:\n\n### 1. Absolute Purchasing Power Parity (PPP)\n$$S = \\frac{P}{P^*}$$\n- $S$: Spot exchange rate (Domestic currency per foreign currency unit, e.g. ₹/USD).\n- $P$: Domestic price level; $P^*$: Foreign price level.\n- *Core Claim*: 1 unit of currency converted at the spot rate buys the identical basket of goods in both countries (The Big Mac Index).\n\n### 2. Relative Purchasing Power Parity (RPPP)\n$$\\frac{S_1 - S_0}{S_0} \\approx \\pi - \\pi^*$$\n- $\\pi$: Domestic inflation rate; $\\pi^*$: Foreign inflation rate.\n- *Core Claim*: The percentage change in the exchange rate equals the inflation rate differential. If India\'s inflation is $6\\%$ and US inflation is $2\\%$, the Rupee should depreciate by approximately $4\\%$ per year.\n\n### 3. Covered Interest Rate Parity (CIP)\n$$\\frac{F - S}{S} = \\frac{i - i^*}{1 + i^*} \\approx i - i^*$$\n- $F$: Forward exchange rate; $S$: Spot exchange rate.\n- $i$: Domestic interest rate (e.g. 7% in India); $i^*$: Foreign interest rate (e.g. 5% in US).\n- *Core Claim*: The forward currency premium/discount eliminates riskless foreign exchange arbitrage. If India\'s interest rates are 2% higher than US rates, the US Dollar must trade at a **2% Forward Premium** against the Rupee ($F > S$).',
        order: 2,
