        body: '```\n                      COVERED vs UNCOVERED INTEREST PARITY\n                                       │\n        ┌──────────────────────────────┴──────────────────────────────┐\n        ▼                                                             ▼\nCOVERED INTEREST RATE PARITY (CIP)                          UNCOVERED INTEREST RATE PARITY (UIP)\n• Arbitrage is completely HEDGED using a Forward contract.  • Arbitrage is UNHEDGED (Exposed to currency risk).\n• Equation: (F - S) / S = i - i*                            • Equation: E(ΔS)/S = i - i*\n• Pure mathematical identity in frictionless markets.       • Investor expects currency with higher interest rate\n• Holds tightly in major convertible interbank markets.       to depreciate by the exact interest differential.\n                                                            • If UIP fails -> Investors execute **CARRY TRADE**\n                                                              (Borrow in cheap Yen/USD, invest in high-yield Rupee).\n```\n\n### Why PPP Fails in the Short Run\nIn reality, PPP does not hold in the short run due to: (1) Transport costs and import tariffs, (2) Non-tradable goods (haircuts, real estate), (3) Sticky nominal prices, and (4) Massive speculative cross-border capital flows ($> 90\\%$ of daily forex turnover is financial investment, not goods trade).',
