        type: 'INTUITION',
        title: 'The National Oxygen Cylinder: Why India Hoards USD 650+ Billion in Reserves',
        body: 'In June 1991, India experienced a catastrophic economic trauma: our foreign exchange reserves dropped to just **US \\USD 1.1 Billionillion**—barely enough to pay for **3 weeks of imports**. India had to pledge 47 tonnes of gold to the Bank of England to avoid defaulting on its sovereign commitments.\n\nThat trauma permanently reshaped Indian policy. Today, the RBI maintains **over US \\USD 650 Billionillion in Foreign Exchange Reserves**.\n\nWhy do we hold this massive financial mountain?\n1. **Precautionary Insurance**: If war erupts, crude oil jumps to US \\$150/barrel, or global investors pull out billions, India has enough foreign currency to keep importing energy, medicine, and food for **over 10 to 11 months** without begging anyone for loans.\n2. **Speculative Deterrence**: Speculators who try to short the Indian Rupee know the RBI has a US \\USD 650 Billionillion war chest to crush speculative attacks.\n\nForeign exchange reserves are the sovereign insurance policy protecting India\'s economic independence.',
