        body: '### Critical Examiner Traps\n- **Trap 1: The Four Components**: Examiners often insert fake components like *"Government of India Domestic Bonds"* or *"Commercial Bank Fixed Deposits"*. Only **FCA, Gold, SDRs, and RTP** form the official reserves.\n- **Trap 2: Guidotti-Greenspan Residual Maturity**: Guidotti-Greenspan measures debt by **Residual Maturity (Original short-term debt + long-term debt maturing in the next 12 months)**, NOT just original short-term debt.\n- **Trap 3: Valuation Effects**: If the US Dollar weakens against the Euro, India\'s reported FCA in US Dollars will **increase automatically** without any fresh dollar purchases by the RBI, due to currency valuation adjustments.\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: Guidotti-Greenspan formula, IMF ARA metric, RTP definition, and multi-currency valuation effects.\n- **UPSC APFC, SBI/IBPS PO & RPSC RAS**: Listing the four components of India\'s foreign exchange reserves and import cover calculations.',
