        type: 'INTUITION',
        title: 'The Fallacy of Spending the Reserves: Why We Cannot Build Highways with Forex',
        body: 'Politicians and columnists frequently propose: *"India has US \\USD 650 Billionillion in foreign exchange reserves sitting idle! Why doesn\'t the government take US \\USD 100 Billionillion to build bullet trains, solar plants, and hospitals?"*\n\nHere is why this proposal is economically catastrophic:\n1. **The Reserves Do Not Belong to the Ministry of Finance**: The RBI did not find US \\USD 650 Billionillion on the street. The RBI bought every single dollar from exporters and foreign investors by printing Indian Rupees. On the RBI balance sheet, the US \\USD 650 Billionillion of foreign assets is **100% matched by ₹55 Lakh Crore of domestic currency liabilities** (the money in your wallet and bank deposits).\n2. **What Happens if the Government "Takes" the Dollars?**:\n   - If the government forces the RBI to give it US \\USD 100 Billionillion for free, the RBI\'s assets drop while liabilities remain, turning the central bank\'s net worth negative and destroying international confidence in the Indian Rupee.\n   - If the government converts those dollars to Rupees to pay Indian contractors, it would inject ₹8.4 Lakh Crore of unsterilized cash into the economy, triggering **runaway hyperinflation**.\n\nForeign exchange reserves are a liquidity buffer against international crises, not a fiscal sovereign wealth fund.',
        order: 1,
