        type: 'INTUITION',
        title: 'The Currency Trap: Why Borrowing in Dollars Destroys Weak Companies',
        body: 'Imagine an Indian airline borrows **US \\USD 100 Millionillion** from an American bank at a cheap $4\\%$ interest rate to buy aircraft. At the time of borrowing, the exchange rate is ₹70 / USD. The airline owes ₹700 Crore.\n\nTwo years later, global financial markets panic, and the Rupee depreciates to ₹85 / USD.\n\nWhat happened to the airline\'s debt?\n- The airline still owes US \\USD 100 Millionillion to the US bank.\n- But in Indian Rupees, its debt has automatically exploded from ₹700 Crore to **₹850 Crore**—an instant loss of ₹150 Crore, even though the airline did nothing wrong!\n- Worse, the airline sells its flight tickets in **Indian Rupees**, but must repay the loan in **US Dollars**.\n\nThis deadly trap is called **Currency Mismatch (or "Original Sin")**: earning revenue in domestic currency while owing debt in foreign currency. If unhedged, currency depreciation can bankrupt even profitable domestic firms.',
        order: 1,
