        type: 'EXAM_APPLICATION',
        title: 'Exam Traps & Multi-Exam Crosswalks',
        body: '### Critical Examiner Traps\n- **Trap 1: Public Debt vs External Debt**: Examiners often conflate the two. **Public Debt** is total debt owed by the government (domestic + external, $\\\\sim 82\\\\%$ of GDP, mostly domestic). **External Debt** is debt owed to non-residents by *everyone* (government + private corporates, $\\\\sim 19\\\\%$ of GDP). Over $95\\\\%$ of India\'s government debt is domestic, NOT external!\n- **Trap 2: Is Rupee Debt Owed to Foreigners External Debt?**: **YES.** Under IMF definition, external debt is determined by the **Residency of the creditor**, not currency. If a foreign fund in London buys Rupee G-Secs, it is part of India\'s External Debt.\n- **Trap 3: Largest Component of External Debt**: Commercial Borrowings (ECBs) form the single largest component ($\\\\sim 32\\\\% - 34\\\\%$), followed by NRI Deposits ($\\\\sim 23\\\\% - 24\\\\%$).\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: Debt service ratio formula, currency composition percentages, ECB hedging mandates, and rollover risk.\n- **UPSC APFC, SBI/IBPS PO & RPSC RAS**: Distinguishing sovereign from non-sovereign external debt and safe DSR thresholds.',
