        title: 'Why Devaluing Your Currency Makes Things Worse Before They Get Better',
        body: 'Imagine India devalues the Rupee by $20\\%$ today to fix a trade deficit. The government expects Indian exports to boom and imports to stop.\n\nWhat happens on Day 1?\n- Indian refiners have already signed contracts to buy 10 Million barrels of oil from Saudi Arabia at US \\$100/barrel. The shipment is already on the high seas.\n- Yesterday, paying for that oil cost ₹7,000 Crore. Today, because the Rupee is 20% cheaper, paying for the *exact same oil* costs **₹8,400 Crore**!\n- Meanwhile, foreign buyers of Indian textiles take 6 to 9 months to renegotiate contracts, build new supply chains, and order more Indian shirts.\n\nOn Day 1, your **import bill explodes in Rupees, while your export volume has not changed yet**. Your trade deficit gets **sharply worse**!\n\nOnly after 6 to 12 months, when Indian companies expand production and foreign buyers switch to cheap Indian goods, does the trade balance recover and surge into surplus. Plotted on a chart, the path traces the letter **"J"**—the **J-Curve Effect**.',
        order: 1,
