        title: 'Mathematical Proof of the Marshall-Lerner Condition',
        body: 'Let the Trade Balance ($TB$) expressed in domestic currency be:\n$$TB = P \\cdot X - S \\cdot P^* \\cdot M$$\n- $X(S)$: Export volume (depends positively on exchange rate $S$);\n- $M(S)$: Import volume (depends negatively on exchange rate $S$);\n- $S$: Nominal exchange rate (Direct quote: ₹/USD).\n\nDifferentiating $TB$ with respect to $S$ and expressing in terms of price elasticities of demand ($e_x = \\frac{dX/X}{dS/S}$ and $e_m = -\\frac{dM/M}{dS/S}$):\n\n$$\\frac{dTB}{dS} = P^* \\cdot M \\cdot \\left[ |e_x + e_m| - 1 \\right]$$\n\n### The Three Elasticity Regimes\n1. **$|e_x + e_m| > 1$ (Elastic Demand)**: $\\frac{dTB}{dS} > 0 \\implies$ **Currency Depreciation Improves Trade Balance** (Marshall-Lerner Holds).\n2. **$|e_x + e_m| = 1$ (Unit Elastic)**: $\\frac{dTB}{dS} = 0 \\implies$ Currency depreciation leaves the trade balance completely unchanged.\n3. **$|e_x + e_m| < 1$ (Inelastic Demand / "Elasticity Pessimism")**: $\\frac{dTB}{dS} < 0 \\implies$ **Currency Depreciation Worsens Trade Balance** (Because price increases on inelastic imports outweigh small volume gains on exports).',
