        body: '```\nTrade Balance\nSurplus (+)\n    ▲\n    │                                              Long-Run Equilibrium\n    │                                              (|ex + em| > 1)\n  0 ├─────────────────────────────────────────/────────────────────► Time\n    │     Devaluation Date                   / (Trade Balance Improves)\n    │            │                          /\nDeficit (-)      ▼       Short-Run Dip     /\n    │            └───────────────\\────────/\n    │                             \\______/  <--- Bottom of J-Curve\n    │                             (Contractual Lag / Currency Pass-Through)\n```\n\n### Policy Taxonomy: Expenditure-Switching vs Expenditure-Reducing (Harry Johnson)\n| Policy Classification | Policy Instruments | Mechanism | Economic Purpose |\n| :--- | :--- | :--- | :--- |\n| **Expenditure-Switching** | • Currency Depreciation / Devaluation\\n• Import Tariffs\\n• Export Subsidies | Changes relative prices ($P_{\\\\text{import}} / P_{\\\\text{domestic}}$), inducing buyers to switch demand from foreign goods to domestic goods. | Redirects existing spending toward domestic output without necessarily cutting total national demand. |\n| **Expenditure-Reducing** | • Monetary Tightening (Hike Repo Rate)\\n• Fiscal Consolidation (Cut Budget Deficit)\\n• Increase Direct Taxes | Compresses total domestic aggregate absorption ($A = C + I + G$). | Shrinks total domestic purchasing power, directly suppressing national import demand. |',
