        body: '### Critical Examiner Traps\n- **Trap 1: Devaluation Instantly Fixes Trade Deficits**: False! Because of the **J-Curve Effect**, a currency depreciation initially *widens* the trade deficit in the short run (3–6 months) before improving it.\n- **Trap 2: When Does Marshall-Lerner Fail?**: If a country exports raw primary commodities with low price elasticity and imports essential crude oil/medicines ($|e_x + e_m| < 1$), devaluation will permanently worsen the trade balance and fuel imported inflation (**Elasticity Pessimism**).\n- **Trap 3: Switching vs Reducing**: Raising interest rates is an **Expenditure-Reducing** policy (cuts aggregate absorption); devaluing the currency is an **Expenditure-Switching** policy (switches spending to domestic goods).\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: Mathematical condition of Marshall-Lerner, J-Curve time lags, and Harry Johnson absorption equations ($CA = Y - A$).\n- **UPSC APFC & RPSC RAS**: Definitions of Marshall-Lerner condition, J-Curve effect, and expenditure-switching vs reducing tools.',
