        body: 'Imagine an international highway with 164 countries driving their commercial trucks:\n1. **Most-Favoured-Nation (MFN) Rule (At the Toll Gate)**: India cannot say: *"If Germany brings steel across the border, the customs toll is 5%, but if Brazil brings steel, the customs toll is 25% because we like Germany more."* Under MFN, **whatever lowest tariff you give to your favorite best friend, you MUST give to every single member of the WTO automatically**!\n2. **National Treatment Rule (Inside the City)**: Once German steel has paid the 5% customs duty and enters Mumbai, Maharashtra cannot pass a law saying: *"Foreign steel must pay a 28% GST, while Tata Steel pays only 18% GST."* Once past the customs gate, imported goods must be treated with **total equality compared to domestic goods**.\n\nThese two rules prevent trade wars, favoritism, and hidden protectionism across the globe.',
