        title: 'The WTO Pillars: Institutional Architecture & Core Agreements',
        body: 'The WTO operates across four foundational covered agreements:\n\n```\n                         THE WTO COVERED AGREEMENTS\n                                      │\n     ┌───────────────────┬────────────┴────────────┬───────────────────┐\n     ▼                   ▼                         ▼                   ▼\n1. GATT 1994            2. GATS (Services)        3. TRIPS (IP Rights)  4. TRIMS (Investment)\n(Trade in Goods)        • Covers 4 Modes of       • Enforces minimum    • Prohibits investment\n• Non-discrimination     Cross-Border Service      standards for         measures that distort\n  (MFN & Nat. Treatment) Supply (Mode 1 to 4).     Patents, Copyrights,  trade (e.g. Local\n• Bound Tariff ceilings • Financial services,      Trademarks, Trade     Content Requirements,\n• Ban on quantitative    Telecomm, IT,             Secrets, and GI       Export Balancing\n  quotas (Art XI).       Professional visas.       Tags (20-yr patents). requirements).\n```\n\n### The Four Modes of Trade in Services under GATS\n- **Mode 1 (Cross-Border Supply)**: Service crosses border; supplier and consumer stay in their countries (e.g., Indian software firm emailing code to New York).\n- **Mode 2 (Consumption Abroad)**: Consumer travels to supplier\'s country (e.g., American tourist visiting Jaipur; foreign student studying in Delhi).\n- **Mode 3 (Commercial Presence)**: Foreign firm establishes a local branch/subsidiary (e.g., Citibank or HSBC opening bank branches in India).\n- **Mode 4 (Presence of Natural Persons)**: Temporary cross-border movement of individual professionals (e.g., Indian software engineer traveling on an H-1B visa to deploy software on-site in California). *India is the world\'s leading advocate for liberalizing Mode 4!*',
        order: 2,
