        content: 'WTO: Formed Jan 1, 1995 via Marrakesh Agreement (Uruguay Round), HQ Geneva. Core Principles: (1) MFN (GATT Art I: treat all trading partners equally), (2) National Treatment (GATT Art III: treat imported goods equally to domestic goods inside domestic market). Single Undertaking: must accept all agreements. GATS: 4 Modes of Services (Mode 1: Cross-border, Mode 2: Consumption abroad, Mode 3: Commercial presence, Mode 4: Movement of natural persons/professionals).',
