        content: 'The World Trade Organization (WTO) succeeded the provisional GATT 1947 on January 1, 1995, following the Marrakesh Agreement concluding the Uruguay Round. Headquartered in Geneva, it enforces multilateral trade rules under a Single Undertaking. Its bedrock non-discrimination principles are: (1) Most-Favoured-Nation (MFN - GATT Article I), mandating equal treatment across all foreign trading partners; and (2) National Treatment (GATT Article III), prohibiting discrimination against foreign goods via internal taxes once past customs. Covered agreements include GATT (Goods), GATS (Services across 4 modes of supply), TRIPS (Intellectual property protection for 20-year patents), and TRIMS (banning trade-distorting investment measures).',
