        title: 'The Great Wheat War: Why India\'s MSP Angers Western Farm Lobbyists',
        body: 'Why does India\'s Minimum Support Price (MSP) for rice and wheat spark furious arguments in Geneva?\n\n- Under the **WTO Agreement on Agriculture (AoA)** signed in 1994, trade-distorting farm subsidies (**Amber Box**) for developing nations cannot exceed **10% of the total value of production (De Minimis limit)**.\n- Here is the catch: The WTO calculates market support using a fixed historical global benchmark price from **1986–1988** (when global wheat was US \\$140/tonne)!\n- When India buys wheat at ₹2,275 per quintal in 2024 to feed 80 Crore poor citizens under the National Food Security Act (NFSA), the WTO\'s outdated 1988 formula makes it look like India is subsidizing farmers by over $50\\%$, technically breaching the 10% limit.\n\nTo prevent the US and EU from suing India and halting food rations, India fought for and won the **Bali Peace Clause (2013)**—legally protecting our food security procurement from global lawsuits.',
