        body: 'The WTO is unique among international institutions because it has "teeth" (a binding legal dispute resolution court):\n\n```\n                    WTO DISPUTE SETTLEMENT TIMELINE\n                                   │\n     1. BILATERAL CONSULTATIONS (60 Days mandatory good-faith talks)\n                                   │ (If unresolved)\n                                   ▼\n     2. DISPUTE SETTLEMENT PANEL (Expert legal panel examines case; 6-9 months)\n                                   │ (Issue Panel Report)\n                                   ▼\n     3. APPELLATE BODY (7-member permanent appeal court; upholds/modifies findings)\n                                   │ (Final binding ruling)\n                                   ▼\n     4. IMPLEMENTATION & RETALIATION (If losing member fails to comply, winning\n                                      member is authorized to levy retaliatory tariffs)\n```\n\n### The Appellate Body Crisis\nThe WTO Appellate Body requires a minimum of **3 judges** to hear an appeal. Since 2019, the United States has vetoed the appointment of new judges, leaving the Appellate Body with **zero judges**. Today, losing countries can file an "appeal into the void" (an appeal that cannot be heard), effectively paralyzing the multilateral enforcement system.',
