        type: 'INTUITION',
        title: 'The Global Emergency Credit Card: Understanding the IMF',
        body: 'Imagine a neighborhood credit union formed by 190 countries:\n1. **The Subscription (Quota)**: Every country contributes money to the pool based on the size of its economy. The USA puts in the most, India puts in a substantial amount, and smaller nations contribute less.\n2. **The Voting Rules**: Unlike the United Nations General Assembly (where every country gets 1 equal vote), the IMF is a **shareholder financial institution**—voting power is directly tied to the size of your Quota subscription. The US holds $\\\\sim 16.5\\\\%$ of the votes, while major decisions require an **$85\\%$ supermajority**, giving Washington an absolute single-handed veto!\n3. **The SDR (Special Drawing Right)**: To ensure countries don\'t run out of international liquidity, the IMF created its own artificial accounting currency called the **SDR** (a synthetic cocktail of Dollars, Euros, Yuan, Yen, and Pounds).\n\nThe IMF does not build schools or dams—it acts as the global macroeconomic fire department to extinguish Balance of Payments crises.',
