        content: 'IMF: Created 1944 at Bretton Woods, HQ Washington D.C. Mandate: International monetary stability & BoP financing. Quota determines financial subscription, voting power, and borrowing access (Formula: GDP 50%, Openness 30%, Variability 15%, Reserves 5%). US holds ~16.5% vote (veto over 85% decisions). SDR (Special Drawing Right): Reserve asset based on 5-currency basket (USD, EUR, CNY, JPY, GBP).',
