        type: 'INTUITION',
        title: 'The Hospital with Painful Medicine: Why Countries Avoid the IMF',
        body: 'Nobody goes to the IMF for fun. A nation knocks on the IMF\'s door in Washington only when it is in the macroeconomic "Intensive Care Unit (ICU)"—its foreign exchange reserves have run out, global banks refuse to lend, and foreign default is days away.\n\nIn 1991, India was in that exact ICU. The IMF agreed to provide an **Extended Fund Facility (EFF) loan of US \\USD 2.2 Billionillion** to save India from sovereign default.\n\nBut the loan came with **"Conditionality" (Bitter Medicine)**:\n- Devalue the Rupee by 19%.\n- Cut the fiscal deficit and eliminate industrial subsidies.\n- Dismantle the License-Permit Raj and open the economy to foreign trade and investment.\n\nConditionality ensures that the borrowing country fixes its structural sickness so it can earn foreign exchange, restore stability, and repay the IMF.',
        order: 1,
