        title: 'Exam Traps & Multi-Exam Crosswalks',
        body: '### Critical Examiner Traps\n- **Trap 1: IMF Does Not Finance Projects**: If India needs US \\USD 1 Billionillion to build a metro rail line or irrigation dam, it goes to the **World Bank (IBRD/IDA) or ADB**, NOT the IMF. The IMF finances **macroeconomic Balance of Payments shortfalls only**.\n- **Trap 2: Is India an IMF Debtor Today?**: **NO.** India has had zero outstanding debt to the IMF since the year 2000. India is a contributor/creditor to the IMF.\n- **Trap 3: Article IV Surveillance Mandate**: Article IV consultations are **mandatory for all member countries** (including the USA, China, and India), but the IMF has no legal power to force sovereign governments to adopt its Article IV policy recommendations.\n\n### Cross-Exam Focus\n- **RBI Grade B & SEBI Grade A**: Distinguishing SBA, EFF, FCL, and PRGT facilities, Article IV surveillance mechanism, and Reserve Tranche unconditional liquidity.\n- **UPSC APFC & RPSC RAS**: India\'s 1991 EFF program, structural conditionality, and IMF vs World Bank mandates.',
