        type: 'INTUITION',
        title: 'The Bretton Woods Twins: Who Does What in Washington?',
        body: 'Walk down Pennsylvania Avenue in Washington D.C., and you will see the **IMF** and the **World Bank** facing each other across the street. Both were born at the 1944 Bretton Woods Conference. What is the difference between them?\n\n- **The IMF is the Emergency Firefighter**: If a country runs out of foreign exchange to pay for next week\'s food and fuel imports, the IMF rushes in with emergency liquidity to save the currency from crashing.\n- **The World Bank is the Master Builder**: The World Bank does not handle short-term currency crises. It funds 30-year highways, rural water pipelines, solar power grids, school systems, and poverty alleviation programs.\n- **The WTO (in Geneva) is the Traffic Police**: It does not lend any money at all. It writes the legal trade rules so countries don\'t block each other\'s exports.\n\nUnderstanding this division of labor is essential for all civil service and financial examinations.',
